static void snd_init(void){memset(&apar,0,sizeof(apar));apar.numChannels=2;apar.numBlocks=8;apar.attr=0;apar.level=1.0f;if(audioInit()!=0)return;if(audioPortOpen(&apar,&aport)!=0)return;if(audioGetPortConfig(aport,&aconf)!=0)return;audio_ok=1;}
static void snd_beep(int freq,int dur,int type,int vol){if(!audio_ok)return;snd_freq=freq;snd_left=dur;snd_type=type;snd_vol=vol;}
static void snd_update(void){if(!audio_ok||snd_left<=0)return;u64 block=0;if(audioGetPortBlock(0,&block)!=0)return;float *buf=(float*)aconf.readIndex;if(!buf)return;for(int i=0;i<256;i++){float v=0;if(snd_type==0)v=(snd_phase<0.5f)?1.0f:-1.0f;else if(snd_type==1)v=sinf(snd_phase*2*PI);else v=(snd_phase*2-1);snd_phase+=(float)snd_freq/48000.0f;if(snd_phase>=1)snd_phase-=1;float s=v*(snd_vol/32768.0f)*0.25f;for(int c=0;c<aconf.numChannels;c++)buf[i*aconf.numChannels+c]=s;}audioSetPortBlock(0,block);snd_left-=256;if(snd_left<=0)snd_phase=0;}
static void snd_eat(void){snd_beep(520+rand()%200,800,1,9000);}
static void snd_kill(void){snd_beep(180,2200,0,12000);}
