static int state=0,menu_sel=0,skin_sel=2,speed_sel=1,highscore=0,total_kills=0,total_eaten=0,total_games=0,best_len=0,show_help=0,show_rank=0,pause=0,game_mode=0,difficulty=1,muted=0,show_minimap=1,show_fps=0,fps=60,frame=0,beep_t=0;
