int main(int argc,char **argv){(void)argc;(void)argv;init_screen();ioPadInit(7);snd_init();sysUtilRegisterCallback(0,sysutil_cb,NULL);srand(20261109);init_game();while(running){sysUtilCheckCallback();read_pad();if(pad_start&&!start_prev){if(state==0){state=1;init_game();if(!muted)snd_click();}else{pause=!pause;if(!muted)snd_click();}}if(pad_select&&!select_prev){show_minimap=!show_minimap;if(!muted)snd_click();}if(pad_tri&&!tri_prev){show_help=!show_help;show_rank=!show_rank;if(!muted)snd_click();}if(pad_sq&&!sq_prev){muted=!muted;if(!muted)snd_click();}start_prev=pad_start;select_prev=pad_select;tri_prev=pad_tri;sq_prev=pad_sq;if(state==0){if(pad_up&&!up_prev){menu_sel=(menu_sel+6)%7;if(!muted)snd_click();}if(pad_down&&!down_prev){menu_sel=(menu_sel+1)%7;if(!muted)snd_click();}if(pad_left&&!left_prev){if(menu_sel==1)skin_sel=(skin_sel+11)%12;if(menu_sel==2)speed_sel=(speed_sel+2)%3;if(menu_sel==3)difficulty=(difficulty==1?3:1);if(menu_sel==4)game_mode=(game_mode+2)%3;if(menu_sel==6)muted=!muted;if(!muted)snd_click();}if(pad_right&&!right_prev){if(menu_sel==1)skin_sel=(skin_sel+1)%12;if(menu_sel==2)speed_sel=(speed_sel+1)%3;if(menu_sel==3)difficulty=(difficulty==3?1:3);if(menu_sel==4)game_mode=(game_mode+1)%3;if(menu_sel==6)muted=!muted;if(!muted)snd_click();}if(pad_x&&!x_prev){if(menu_sel==5)show_help=!show_help;else if(menu_sel==6)muted=!muted;else{state=1;init_game();}if(!muted)snd_click();}up_prev=pad_up;down_prev=pad_down;left_prev=pad_left;right_prev=pad_right;x_prev=pad_x;render();present();continue;}if(!pause){update_game();}else{if(pad_select){state=0;pause=0;}}render();present();}return 0;}